const NAV = [
  { href: "#services", label: "Services", num: "01" },
  { href: "#work", label: "Work", num: "02" },
  { href: "#reviews", label: "Reviews", num: "03" },
  { href: "#contact", label: "Contact", num: "04" },
]

export default function Section() {
  return (
    <header id="top" className="bg-surface border-b-4 border-secondary-900">
      <Business>
        {b => (
          <div className="mx-auto max-w-7xl flex items-stretch justify-between gap-3 min-h-16 md:min-h-20">
            <Link
              href="#top"
              className="flex min-w-0 items-center gap-3 py-3 pl-4 pr-2 sm:pl-6 md:pr-6 md:border-r-2 md:border-secondary-900"
            >
              {b.logo ? (
                <span className="block h-11 w-11 shrink-0 border-2 border-secondary-900 bg-white overflow-hidden">
                  <Image src={b.logo} alt={b.name} aspect="1:1" fit="contain" priority />
                </span>
              ) : (
                <span className="flex h-11 w-11 shrink-0 items-center justify-center border-2 border-secondary-900 bg-primary-500 font-display text-xl font-bold uppercase text-secondary-900">
                  {b.initial}
                </span>
              )}
              <span className="flex min-w-0 flex-col">
                <span className="truncate font-display text-base font-bold uppercase leading-tight tracking-tight text-secondary-900 sm:text-lg lg:text-xl">
                  {b.name}
                </span>
                {b.profession && (
                  <span className="hidden truncate font-mono text-xs uppercase tracking-widest text-foreground-muted sm:block">
                    {b.profession}
                  </span>
                )}
              </span>
            </Link>

            <nav aria-label="Sections" className="hidden md:flex flex-1 items-stretch justify-center">
              {NAV.map((n, i) => (
                <Link
                  key={n.href}
                  href={n.href}
                  className={`group flex items-center gap-2 px-4 lg:px-6 font-mono text-sm uppercase tracking-widest text-secondary-900 hover:bg-accent-500 border-secondary-900 ${i === 0 ? "border-l-0" : "border-l-2"}`}
                >
                  <span className="text-xs text-foreground-muted group-hover:text-secondary-900">{n.num}</span>
                  <span className="font-bold">{n.label}</span>
                </Link>
              ))}
            </nav>

            <div className="flex shrink-0 items-center py-3 pr-5 sm:pr-7 md:border-l-2 md:border-secondary-900 md:pl-6">
              {(b.whatsappUrl || b.phoneUrl) && (
                <span className="relative inline-block">
                  <span aria-hidden="true" className="absolute inset-0 translate-x-1.5 translate-y-1.5 bg-secondary-900" />
                  <Link
                    href={b.whatsappUrl ? b.whatsappUrl : b.phoneUrl}
                    target={b.whatsappUrl ? "_blank" : "_self"}
                    className="relative flex min-h-11 items-center gap-2 border-2 border-secondary-900 bg-primary-500 px-3 sm:px-5 font-mono text-sm font-bold uppercase tracking-wider text-secondary-900 transition-transform hover:translate-x-1 hover:translate-y-1"
                  >
                    <Icon name={b.whatsappUrl ? "message-circle" : "phone"} size="sm" strokeWidth={2.5} className="text-secondary-900" />
                    <span>{b.whatsappUrl ? "WhatsApp" : "Call"}</span>
                    <span className="hidden lg:inline">{b.whatsappUrl ? "us" : "now"}</span>
                  </Link>
                </span>
              )}
            </div>
          </div>
        )}
      </Business>
    </header>
  )
}
